Extensions.ExtractScript:
param(
    [xml] $Document
);
foreach( $file in $Document.unattend.Extensions.File ) {
    $path = [System.Environment]::ExpandEnvironmentVariables( $file.GetAttribute( 'path' ) );
    mkdir -Path( $path | Split-Path -Parent ) -ErrorAction 'SilentlyContinue';
    $encoding = switch( [System.IO.Path]::GetExtension( $path ) ) {
        { $_ -in '.ps1', '.xml' } { [System.Text.Encoding]::UTF8; }
        { $_ -in '.reg', '.vbs', '.js' } { [System.Text.UnicodeEncoding]::new( $false, $true ); }
        default { [System.Text.Encoding]::Default; }
    };
    $bytes = $encoding.GetPreamble() + $encoding.GetBytes( $file.InnerText.Trim() );
    [System.IO.File]::WriteAllBytes( $path, $bytes );
}

Extensions.File:
$selectors = @(
    'Microsoft.Microsoft3DViewer';
    'Microsoft.MixedReality.Portal';
    'Microsoft.BingNews';
    'Microsoft.BingWeather';
    'Microsoft.549981C3F5F10';
    'Microsoft.WindowsFeedbackHub';
    'Microsoft.GetHelp';
    'Microsoft.Getstarted';
    'microsoft.windowscommunicationsapps';
    'Microsoft.WindowsMaps';
    'Microsoft.MicrosoftOfficeHub';
    'Microsoft.Office.OneNote';
    'Microsoft.MSPaint';
    'Microsoft.People';
    'Microsoft.PowerAutomateDesktop';
    'MicrosoftCorporationII.QuickAssist';
    'Microsoft.SkypeApp';
    'Microsoft.ScreenSketch';
    'Microsoft.MicrosoftSolitaireCollection';
    'Microsoft.Todos';
    'Microsoft.WindowsSoundRecorder';
    'Microsoft.Wallet';
    'Microsoft.Xbox.TCUI';
    'Microsoft.XboxApp';
    'Microsoft.XboxGameOverlay';
    'Microsoft.XboxGamingOverlay';
    'Microsoft.XboxIdentityProvider';
    'Microsoft.XboxSpeechToTextOverlay';
    'Microsoft.GamingApp';
    'Microsoft.YourPhone';
    'Microsoft.ZuneMusic';
    'Microsoft.ZuneVideo';
    'Microsoft.MicrosoftStickyNotes';
    'Microsoft.Windows.Photos';
    'Microsoft.WindowsStore';
    'Microsoft.Print3D';
    'Microsoft.OneConnect';
    'Microsoft.WindowsAlarms';
    'Microsoft.WindowsCamera';
);
$getCommand = { Get-AppxProvisionedPackage -Online; };
$filterCommand = { $_.DisplayName -eq $selector; };
$removeCommand = {
    [CmdletBinding()]
    param([Parameter(Mandatory, ValueFromPipeline)] $InputObject);
    process { $InputObject | Remove-AppxProvisionedPackage -AllUsers -Online -ErrorAction 'Continue'; }
};
$type = 'Package';
$logfile = 'C:\Windows\Setup\Scripts\RemovePackages.log';
& {
    $installed = & $getCommand;
    foreach ($selector in $selectors) {
        $result = [ordered] @{ Selector = $selector; };
        $found = $installed | Where-Object -FilterScript $filterCommand;
        if ($found) {
            $result.Output = $found | & $removeCommand;
            if ($?) { $result.Message = "$type removed."; }
            else { $result.Message = "$type not removed."; $result.Error = $Error[0]; }
        } else {
            $result.Message = "$type not installed.";
        }
        $result | ConvertTo-Json -Depth 3 -Compress;
    }
} *>&1 >> $logfile;

$selectors = @(
    'Print.Fax.Scan';
    'Language.Handwriting';
    'MathRecognizer';
    'OneCoreUAP.OneSync';
    'App.Support.QuickAssist';
    'Language.Speech';
    'Language.TextToSpeech';
    'App.StepsRecorder';
    'Media.WindowsMediaPlayer';
    'Microsoft.Windows.WordPad';
);
$getCommand = {
    Get-WindowsCapability -Online | Where-Object -Property 'State' -NotIn -Value @('NotPresent'; 'Removed';);
};
$filterCommand = { ($_.Name -split '~')[0] -eq $selector; };
$removeCommand = {
    [CmdletBinding()]
    param([Parameter(Mandatory, ValueFromPipeline)] $InputObject);
    process { $InputObject | Remove-WindowsCapability -Online -ErrorAction 'Continue'; }
};
$type = 'Capability';
$logfile = 'C:\Windows\Setup\Scripts\RemoveCapabilities.log';
& {
    $installed = & $getCommand;
    foreach ($selector in $selectors) {
        $result = [ordered] @{ Selector = $selector; };
        $found = $installed | Where-Object -FilterScript $filterCommand;
        if ($found) {
            $result.Output = $found | & $removeCommand;
            if ($?) { $result.Message = "$type removed."; }
            else { $result.Message = "$type not removed."; $result.Error = $Error[0]; }
        } else {
            $result.Message = "$type not installed.";
        }
        $result | ConvertTo-Json -Depth 3 -Compress;
    }
} *>&1 >> $logfile;

$log = "$env:TEMP\UserOnce.log"
function Log { param($m) "$(Get-Date -f 'HH:mm:ss') $m" | Out-File $log -Append -Encoding UTF8 }
Log '=== UserOnce.ps1 iniciado ==='

# Efeitos visuais customizados
Set-ItemProperty -LiteralPath 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' -Name 'VisualFXSetting' -Type 'DWord' -Value 3 -Force -ErrorAction SilentlyContinue

# Tema Escuro no Windows 10
$themeKey = 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize'
Set-ItemProperty -LiteralPath $themeKey -Name 'SystemUsesLightTheme' -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
Set-ItemProperty -LiteralPath $themeKey -Name 'AppsUseLightTheme' -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
Set-ItemProperty -LiteralPath $themeKey -Name 'EnableTransparency' -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue

# Papel de parede: preto solido (economiza memoria)
try {
    Add-Type -TypeDefinition '
using System; using System.Drawing; using System.Runtime.InteropServices;
public class WP {
    [DllImport("user32.dll")] public static extern bool SystemParametersInfo(uint a,uint b,string c,uint d);
    [DllImport("user32.dll")] public static extern bool SetSysColors(int n, int[] e, int[] v);
}' -ReferencedAssemblies 'System.Drawing' -ErrorAction Stop
    [WP]::SystemParametersInfo(20, 0, "", 0) | Out-Null
    [WP]::SetSysColors(1, @(1), @(0)) | Out-Null
    Set-ItemProperty 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers' -Name 'BackgroundType' -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
    Set-ItemProperty 'Registry::HKCU\Control Panel\Desktop' -Name 'WallPaper' -Value '' -Type String -Force -ErrorAction SilentlyContinue
    Set-ItemProperty 'Registry::HKCU\Control Panel\Colors' -Name 'Background' -Value '0 0 0' -Type String -Force -ErrorAction SilentlyContinue
} catch {
    Log "Aviso ao configurar papel de parede: $($_.Exception.Message)"
}

# Cor de acento Azul #0078D4
try {
    Add-Type -AssemblyName 'System.Drawing'
    $accent = [System.Drawing.ColorTranslator]::FromHtml('#0078D4')
    $dword = [System.BitConverter]::ToUInt32([byte[]]@($accent.R, $accent.G, $accent.B, $accent.A), 0)
    Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\DWM' -Name 'AccentColor' -Value $dword -Type DWord -Force -ErrorAction SilentlyContinue
} catch {}

Start-Sleep -Seconds 1
Get-Process -Name 'explorer' -ErrorAction SilentlyContinue | Where-Object {
    $_.SessionId -eq (Get-Process -Id $PID).SessionId
} | Stop-Process -Force
Log '=== UserOnce.ps1 concluido ==='
